int LIPAT(int n) {
  if (n == 1) {
    return 1;
  }
  return 2 * LIPAT(n / 2);
}

int KODE(int n) {
  return 2 * (n - LIPAT(n)) + 1;
}

int TUNGGAL(int n) {
  int total = 0;
  for (int i = 1; i <= n; i++) {
    total += KODE(i);
  }
  return total;
}

